    const ts = (e.timestamp && e.timestamp._seconds) ? e.timestamp._seconds * 1000 : (e.timestamp && e.timestamp.toMillis ? e.timestamp.toMillis() : 0);
    if (ts > a.last_ts) { a.last_ts = ts; a.last_action = e.action || ''; }
