const VAULT_KMS_KEY_VERSION_E2 = ('projects/' + PC_PROJECT + '/locations/' + VAULT_KMS_LOCATION + '/keyRings/' + VAULT_KMS_KEYRING + '/cryptoKeys/' + VAULT_KMS_KEY_E2_NAME + '/cryptoKeyVersions/1');
